head.script:
//
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": "https://www.tayninhinfo.com/#website",
      "url": "https://www.tayninhinfo.com/",
      "name": "TNHub Tây Ninh",
      "description": "Cổng thông tin việc làm, bất động sản và kết nối số tỉnh Tây Ninh",
      "publisher": {
        "@type": "Organization",
        "name": "TNHub Tây Ninh",
        "url": "https://www.tayninhinfo.com/",
        "logo": {
          "@type": "ImageObject",
          "url": "https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=600&h=600&q=80"
        }
      },
      "potentialAction": {
        "@type": "SearchAction",
        "target": "https://www.tayninhinfo.com/?q={search_term_string}",
        "query-input": "required name=search_term_string"
      }
    },
    {
      "@type": "LocalBusiness",
      "@id": "https://www.tayninhinfo.com/#localbusiness",
      "name": "TNHub - Cổng Kết Nối Số Tây Ninh",
      "url": "https://www.tayninhinfo.com/",
      "telephone": "0908123456",
      "priceRange": "$",
      "address": {
        "@type": "PostalAddress",
        "addressLocality": "Tây Ninh",
        "addressRegion": "Tây Ninh",
        "addressCountry": "VN"
      },
      "geo": {
        "@type": "GeoCoordinates",
        "latitude": 11.3117,
        "longitude": 106.0988
      }
    }
  ]
}
//

//
(function(){
  try {
    const origWarn = console.warn;
    console.warn = function() {
      if (arguments[0] && typeof arguments[0] === 'string' && arguments[0].indexOf('cdn.tailwindcss.com') !== -1) {
        return;
      }
      origWarn.apply(console, arguments);
    };
  } catch(e) {}
})();
//

tailwind.config = {
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        oracle: {
          red: '#C74634',
          hover: '#B13C2C',
          dark: '#161513',
          warm: '#F1EFED',
          border: '#E0DDD8',
          charcoal: '#312E2B',
          yellow: '#F1B13F'
        },
        tnhub: {
          50: '#fdf3f2',
          100: '#fbe4e2',
          500: '#C74634',
          600: '#B13C2C',
          700: '#9B3325',
          800: '#7E2A1E',
          900: '#161513'
        }
      }
    }
  }
}

head.b:skin:
* {
  border-radius: 0px !important;
}
body {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  height: 100vh;
  height: 100dvh;
  width: 100vw;
  overflow: hidden;
  background-color: #F1EFED;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #161513;
  display: flex;
}
@media (min-width: 640px) {
  body {
    padding: 12px;
  }
}
@media (min-width: 1024px) {
  body {
    padding: 16px;
  }
}
.custom-scroll::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
.custom-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.custom-scroll::-webkit-scrollbar-thumb {
  background: #C74634;
  border-radius: 0px !important;
}
[v-cloak] {
  display: none !important;
}

div.v-for:
(item, mIdx) in (selectedFoodCard.menuItems || [
                  { name: "Món ăn đặc sản / Phòng tiêu chuẩn", price: selectedFoodCard.price, desc: "Được chế biến tươi ngon trong ngày, phục vụ chu đáo." },
                  { name: "Set ẩm thực trải nghiệm trọn vị Tây Ninh", price: "Thương lượng", desc: "Bao gồm các món truyền thống và tráng miệng đặc sản." }
                ])

div.v-bind:class:
{
             "bg-emerald-50 border-emerald-500 text-emerald-900": toast.type === "success",
             "bg-rose-50 border-rose-500 text-rose-900": toast.type === "error",
             "bg-amber-50 border-amber-500 text-amber-900": toast.type === "warning",
             "bg-blue-50 border-blue-500 text-blue-900": toast.type === "info"
           }

{
               "bg-emerald-100 text-emerald-600": popup.type === "success",
               "bg-rose-100 text-rose-600": popup.type === "error",
               "bg-amber-100 text-amber-600": popup.type === "warning",
               "bg-blue-100 text-blue-600": popup.type === "info"
             }

button.v-bind:class:
{
                    "bg-slate-900 hover:bg-slate-800 text-white": popup.type === "success" || popup.type === "info",
                    "bg-rose-600 hover:bg-rose-700 text-white": popup.type === "error",
                    "bg-amber-600 hover:bg-amber-700 text-white": popup.type === "warning"
                  }

div.p:
Hotline/Zalo: 
{{ selectedDetailCard.phone || '0908.123.456' }}
{{ maskPhoneNumber(selectedDetailCard.phone) }} {{ t('hiddenFree') }}

