const translateDynamicText = (text, lang) => { if (!text || typeof text !== 'string' || lang === 'vi') return text; const pMap = postPhraseMap[lang]; if (!pMap) return text; if (pMap[text]) return pMap[text]; let result = text; const keys = Object.keys(pMap).sort((a, b) => b.length - a.length); for (const k of keys) { if (result.indexOf(k) !== -1) { result = result.split(k).join(pMap[k]); } } return result; };
const getPostTitle = (card) => { if (!card) return ''; const lang = currentLang.value || 'vi'; if (lang === 'vi') return card.title || ''; if (card.title && postTranslations[card.title] && postTranslations[card.title][lang] && postTranslations[card.title][lang].title) { return postTranslations[card.title][lang].title; } return translateDynamicText(card.title || '', lang); };
const getPostDescription = (card) => { if (!card) return ''; const lang = currentLang.value || 'vi'; const rawDesc = card.description || card.subtitle || ''; if (lang === 'vi') return rawDesc; if (card.title && postTranslations[card.title] && postTranslations[card.title][lang] && postTranslations[card.title][lang].desc) { return postTranslations[card.title][lang].desc; } return translateDynamicText(rawDesc, lang); };
const getPostPrice = (card) => { if (!card || !card.price) return ''; const lang = currentLang.value || 'vi'; return translateDynamicText(card.price, lang); };
const getPostSubprice = (card) => { if (!card || !card.subprice) return ''; const lang = currentLang.value || 'vi'; return translateDynamicText(card.subprice, lang); };
const getPostLocation = (card) => { if (!card) return 'Tây Ninh'; const lang = currentLang.value || 'vi'; const loc = card.subtitle || card.location || 'Tây Ninh'; return translateDynamicText(loc, lang); };
const getPostBadge = (card) => { if (!card || !card.badge) return ''; const lang = currentLang.value || 'vi'; return translateDynamicText(card.badge, lang); };
const getPostHours = (card) => { if (!card || !card.foodHours) return 'Mở cả ngày'; const lang = currentLang.value || 'vi'; return translateDynamicText(card.foodHours, lang); };
const getSpecLabel = (spec) => { if (!spec || !spec.label) return ''; const lang = currentLang.value || 'vi'; return translateDynamicText(spec.label, lang); };
const getSpecValue = (spec) => { if (!spec || !spec.val) return ''; const lang = currentLang.value || 'vi'; return translateDynamicText(spec.val, lang); };
const getCommentText = (cmt) => { if (!cmt || !cmt.text) return ''; const lang = currentLang.value || 'vi'; return translateDynamicText(cmt.text, lang); };
