// HỆ THỐNG REALTIME NOTIFICATIONS (THÔNG BÁO THỜI GIAN THỰC) const notifications = ref([]); const unreadNotificationCount = ref(0); const showNotificationDropdown = ref(false); let notifUnsubscribe = null; let globalNotifUnsubscribe = null; let userNotifsList = []; let globalNotifsList = [];
const toggleNotificationDropdown = () => { showNotificationDropdown.value = !showNotificationDropdown.value; };
const updateCombinedNotifs = () => { const map = new Map(); const myEmail = (currentUser.value && currentUser.value.email ? currentUser.value.email : '').toLowerCase().trim();
userNotifsList.forEach(n => map.set(n.id, n)); globalNotifsList.forEach(n => { // Không nhận thông báo từ bài đăng do chính mình tạo if (n.senderEmail && n.senderEmail.toLowerCase().trim() === myEmail) return; if (!map.has(n.id)) { map.set(n.id, n); } });
const combined = Array.from(map.values()); combined.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || '')); notifications.value = combined; unreadNotificationCount.value = combined.filter(n => !n.read).length; };
const markAllNotificationsAsRead = async () => { unreadNotificationCount.value = 0; notifications.value.forEach(n => { n.read = true; }); if (db && currentUser.value) { try { for (const n of notifications.value) { if (n.id && !n.id.startsWith('temp_') && n.scope !== 'funded_and_admin') { updateDoc(doc(db, 'notifications', n.id), { read: true }); } } } catch (e) { console.warn('Lỗi markAllNotificationsAsRead:', e); } } };
const handleNotificationClick = async (notif) => { if (!notif) return; notif.read = true; unreadNotificationCount.value = notifications.value.filter(n => !n.read).length; showNotificationDropdown.value = false;
if (db && notif.id && !notif.id.startsWith('temp_') && notif.scope !== 'funded_and_admin') { try { await updateDoc(doc(db, 'notifications', notif.id), { read: true }); } catch(e) {} }
if (notif.type === 'private_chat') { openPrivateChat({ email: notif.senderEmail, name: notif.senderName, avatar: notif.senderAvatar }); } else if (notif.type === 'comment' && notif.targetPostId) { openDetailModal({ id: notif.targetPostId }); } else if (notif.type === 'global_new_post' && notif.postId) { // Người dùng có nạp tiền hoặc Admin nhấn xem bài đăng mới activeTab.value = 'feed'; if (notif.category && notif.category !== 'all') { activeCategory.value = notif.category; } else { activeCategory.value = 'all'; } const foundCard = cards.value.find(c => c.id === notif.postId); if (foundCard) { if (foundCard.category === 'amthuc') { openFoodDetailPage(foundCard); } else { openDetailModal(foundCard); } } else { openDetailModal({ id: notif.postId }); } } };
const clearNotification = async (notifId) => { notifications.value = notifications.value.filter(n => n.id !== notifId); unreadNotificationCount.value = notifications.value.filter(n => !n.read).length; if (db && notifId) { try { await deleteDoc(doc(db, 'notifications', notifId)); } catch(e) {} } };
const listenRealtimeNotifications = (email) => { if (!db || !email) return; if (notifUnsubscribe) { notifUnsubscribe(); notifUnsubscribe = null; } if (globalNotifUnsubscribe) { globalNotifUnsubscribe(); globalNotifUnsubscribe = null; }
