// HÀM PHÁT THÔNG BÁO GLOBAL KHI BẤT KỲ AI ĐĂNG BÀI VIẾT MỚI const sendGlobalPostNotification = async (card) => { if (!db || !card) return; const author = card.authorName || (currentUser.value ? currentUser.value.displayName : 'Thành viên Tây Ninh'); const authorEmail = (currentUser.value && currentUser.value.email ? currentUser.value.email : (card.authorEmail || '')).toLowerCase().trim(); const title = card.title || 'Tin đăng mới'; const loc = card.location || 'Tây Ninh'; const categoryLabel = getCategoryLabel(card.category); const priceText = card.price ? (' • Giá: ' + card.price) : '';
