const likeComment = (comment, card) => { if (!comment || typeof comment !== 'object' || !comment.id) return; const cmtId = comment.id; const currentlyLiked = isCommentLiked(cmtId) || !!comment.likedByMe; if (currentlyLiked) { // Bỏ thích bình luận const idx = myLikedComments.value.indexOf(cmtId); if (idx > -1) myLikedComments.value.splice(idx, 1); comment.likedByMe = false; comment.likes = Math.max(0, (comment.likes || 1) - 1); showToast(t('unlikeSuccess') || 'Đã bỏ thích bình luận', 'info'); } else { // Thích bình luận ngay lập tức if (!myLikedComments.value.includes(cmtId)) { myLikedComments.value.push(cmtId); } comment.likedByMe = true; comment.likes = (comment.likes || 0) + 1; showToast(t('likeSuccess') || 'Đã thích bình luận!', 'success'); }
try { localStorage.setItem('tnhub_liked_comments', JSON.stringify(myLikedComments.value)); } catch(e) {}
const targetCard = card || selectedDetailCard.value || activeCommentCard.value; if (targetCard && targetCard.id) { // Đồng bộ giữa modal chi tiết, dialog bình luận và card ngoài feed if (selectedDetailCard.value && selectedDetailCard.value.id === targetCard.id) { const cmtInModal = (selectedDetailCard.value.comments || []).find(c => c.id === comment.id); if (cmtInModal) { cmtInModal.likes = comment.likes; cmtInModal.likedByMe = comment.likedByMe; } } if (activeCommentCard.value && activeCommentCard.value.id === targetCard.id) { const cmtInDlg = (activeCommentCard.value.comments || []).find(c => c.id === comment.id); if (cmtInDlg) { cmtInDlg.likes = comment.likes; cmtInDlg.likedByMe = comment.likedByMe; } } const cmtInCard = (targetCard.comments || []).find(c => c.id === comment.id); if (cmtInCard) { cmtInCard.likes = comment.likes; cmtInCard.likedByMe = comment.likedByMe; }
if (db && Array.isArray(targetCard.comments)) { try { setDoc(doc(db, 'listings', targetCard.id), { commentsJson: JSON.stringify(targetCard.comments) }, { merge: true }) .catch(e => console.warn('Sync like cmt error:', e)); } catch (e) { console.warn('Sync like cmt:', e); } } } };
