// TÍNH NĂNG XÓA BÀI ĐĂNG DÀNH CHO ADMIN (ptquang0968@gmail.com) const confirmDeletePost = (card) => { if (!card || !card.id) return; showPopup( 'Xác Nhận Xóa Bài Đăng (Admin)', 'Bạn có chắc chắn muốn xóa vĩnh viễn bài đăng:\n"' + (card.title || 'Bài viết này') + '"\nkhỏi hệ thống cơ sở dữ liệu không?', 'error', 'Xóa vĩnh viễn', async () => { await executeDeletePost(card); }, true, 'Hủy bỏ' ); };
