, val: postForm.value.foodHours }); if (postForm.value.foodAmenity) specs.push({ label: 'Tiện ích', val: postForm.value.foodAmenity }); }
const newCard = { id: 'tn_' + Date.now(), badge: postForm.value.badge || 'Mới đăng', image: postForm.value.imageBase64 || postForm.value.previewUrl || 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80', title: postForm.value.title, subtitle: (postForm.value.address ? postForm.value.address + ' - ' : '') + locName, price: postForm.value.price || 'Thỏa thuận', subprice: postForm.value.subprice || 'Vừa xong', category: postForm.value.category, btnType: postForm.value.category === 'tuyendung' ? 'apply' : (postForm.value.category === 'suachua' ? 'call' : 'contact'), location: locName, district: postForm.value.district, description: postForm.value.description, specs: specs, authorName: postForm.value.contactName || (currentUser.value ? currentUser.value.displayName : 'Phạm Thanh Quang'), phone: postForm.value.contactPhone || '0908.123.456', authorEmail: currentUser.value ? currentUser.value.email : 'ptquang0968@gmail.com', isVip: isFundedUser.value || isAdmin.value, isFunded: isFundedUser.value || isAdmin.value, authorIsFunded: isFundedUser.value || isAdmin.value, userId: currentUser.value ? currentUser.value.uid : '', createdAt: new Date().toISOString(), likesCount: 1, likedByMe: false, viewsCount: 1, showComments: false, newCommentText: '', comments: [] };
cards.value.unshift(newCard);
