const loginGoogle = async () => { try { if (!auth) throw new Error('Firebase Auth chưa khởi tạo'); const provider = new GoogleAuthProvider(); provider.setCustomParameters({ prompt: 'select_account' }); const res = await signInWithPopup(auth, provider); currentUser.value = { uid: res.user.uid, displayName: res.user.displayName, email: res.user.email, photoURL: res.user.photoURL }; showToast('Chào mừng ' + (res.user.displayName || '') + '! Đã đăng nhập Google.', 'success'); return true; } catch (err) { console.warn('Login Auth info:', err.message); showToast('Đang ở phiên làm việc của ptquang0968@gmail.com', 'info'); return false; } };
const logoutGoogle = async () => { try { if (auth) await signOut(auth); currentUser.value = null; showToast(t('logoutSuccess'), 'info'); } catch (e) { console.warn('Signout err:', e); } };
// ========================================== // CÁC HÀM XỬ LÝ PROFILE, BÀI ĐĂNG CỦA TÔI, BẠN BÈ, CHAT PRIVATE // ========================================== const myPostsCount = computed(() => { if (!currentUser.value) return 0; const myEmail = currentUser.value.email || ''; const myUid = currentUser.value.uid || ''; return cards.value.filter(c => (myEmail && c.authorEmail === myEmail) || (myUid && c.userId === myUid)).length; });
const isMyPost = (card) => { if (!currentUser.value || !card) return false; return (card.authorEmail && card.authorEmail === currentUser.value.email) || (card.userId && card.userId === currentUser.value.uid); };
